// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the owner initially
        vm.assume(caller != c.owner());

        // Try to call owned() as the non-owner caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // The general rule: non-owner calls to owned() must revert
        assertTrue(success == false);
    }
}

